import { describe, expect, it } from 'vitest';
import deck from '../../worker/data/the-and-deck.json' with { type: 'json' };
import { GLYPHS } from './glyphs.ts';

// Lives next to the glyphs it checks against; the deck itself is generated by scripts/build-deck.ts.
describe('The And deck', () => {
  it('has the 183 transcribed cards and the custom ones, without the placeholder rows', () => {
    expect(deck).toHaveLength(184);
    expect(deck.at(-1)?.id).toBe('200');
  });

  it('gives every card a unique id', () => {
    expect(new Set(deck.map((card) => card.id)).size).toBe(deck.length);
  });

  it('gives every card text and a card type', () => {
    expect(deck.filter((card) => !card.text.trim() || !card.type)).toEqual([]);
  });

  it('has a chosen glyph for every card type', () => {
    const types = new Set(deck.map((card) => card.type));
    expect([...types].filter((type) => !(type in GLYPHS))).toEqual([]);
  });
});
